        /* since a control is a library function, basically anything can be a source of taint. All properties are of the form getFoo */
        name matches "get[A-Z][A-z0-9]*" 
        /* getId is always on controls and would lead to FPs as is very unlikely user-controlled, so is excluded */
        and not name == "getId"
    ]*
    and fc.instance is [Expression e: 
        /* the standard name is oControl, meaning the control with hungarian notation */
        e is [Location: name == "oControl"]
    ]
    and enclosingFunction is [Function f: parameters.length == 2 and f.name matches "render(er)?"]

FunctionModel.Code:
function render() {
    var itemsCount = this.getItemCount(this.data);
    for (var i = 0; i < itemsCount; i++) {
        var element = this.getItem(this.data, i);
        var callbackObjectItem = {
            item: element,
            index: i
        };
        this.renderItem(callbackObjectItem);
    }
}

function render() {
    for (var i = 0; i < this.sections.length; i++) {
        var callbackObjectSection = {
            section: this.sections[i]
        };
        this.renderSectionHeader(callbackObjectSection);
        var elements = this.sections[i].data;
        for (var j = 0; j < elements.length; j++) {
            var callbackObjectItem = {
                item: elements[j],
                index: i
            };
            this.renderItem(callbackObjectItem);
        }
    }
}

function render() {
    for (var i = 0; i < this.data.length; i++) {
        var callbackObjectItem = {
            item: this.data[i],
            index: i
        };
        this.renderItem(callbackObjectItem);
    }
}

CharacterizationRule.StructuralMatch:
FunctionCall fc: fc.possibleTargets contains [Function: 
        name matches "set|ensureExists|insert|push"
    ]
    // likely sufficient to check for withInheritedProps
    and fc.instance is [Location: name == "withInheritedProps"]
    // cannot do dual-sinks with characterization
    // so just flag on path argument
    and arguments[1] is [Expression path: ]

FunctionCall fc: fc.possibleTargets contains [Function: 
        name == "set"
        and (
            fc.instance is [Location: name matches "(?i)dotProp|dp"]
            // or knowingly comes from dot-prop lib
            or possibleHeapPaths contains "dot-prop"
            // or not defined on an instance
            or fc.instance.null
            // or defined on "Window" (really the default when not set on an instance in client-side code)
            or fc.instance.type is [Type: name matches "(?i)Window"]
        )
    ]
    and fc.arguments.length == 3
    // cannot do dual-sinks with characterization
    // so just flag on path argument
    and arguments[1] is [Expression path: ]

FunctionCall fc: fc.possibleTargets contains [Function: 
        name == "setPathValue"
    ]
    and fc.instance is [Location: name matches "(?i)pathval"]
    // cannot do dual-sinks with characterization
    // so just flag on path argument
    and arguments[1] is [Expression path: ]

FunctionCall fc: fc.possibleTargets contains [Function: 
        name matches "set(With)?"
    ]
    and fc.instance is [Location: name matches "(?i)_|lodash|lod"]
    // cannot do dual-sinks with characterization
    // so just flag on path argument
    and arguments[1] is [Expression path: ]

FunctionCall fc: (fc.possibleTargets contains [Function: 
        name == "deap"
        or (
            name matches "extend|merge"
            and (
                fc.instance is [Location: name == "deap"]
                or possibleHeapPaths contains "deap"
            )
        )
    ]
    or fc.name == "deap"
    )
    and arguments contains [Expression arg: 
        // don't trigger on destination object
        arg != fc.arguments[0]
    ]

