    TaintSink(arg, [(WEB || NETWORK || DATABASE || LDAP || XML || OPEN_XML || FORM || NAMING || GUI_FORM || WEBSERVICE) && JS_OBJECT_CONTROLLED && !NUMBER && !VALIDATED_PROTOTYPE_POLLUTION])
}

CharacterizationRule.StructuralMatch:
FunctionCall fc: fc.possibleTargets contains [Function: 
        (
            name == "mergeOptions"
            or (
                name matches "call|apply"
                and fc.instance is [Location: name == "mergeOptions"]
            )
            // try to account for when unresolved due to import type
            or (
                name == "prototype"
                and fc.name == "mergeOptions"
            )
        )
    ]
    and arguments contains [Expression arg: 
        // do not match on config object in call/apply variants
        not type.definition.fields contains [Field: name == "concatArrays"]
    ]

