CharacterizationRule.StructuralMatch:
FunctionCall fc: (
        fc.possibleTargets contains [Function: 
            // called mergeObjects & mergeDeep in associated library code
            // just called "merge" inside examples for both libraries though
            name matches "mergeObjects|merge|mergeDeep"
            and (
                // comes from merge-objects import
                possibleHeapPaths contains "merge-objects"
                // or comes from merge-deep import
                or possibleHeapPaths contains "merge-deep"
                // or not defined on an instance
                or fc.instance.null
                // or defined on "Window" (really the default when not set on an instance in client-side code)
                or fc.instance.type is [Type: name matches "(?i)Window"]
            )
        ]
        // or if the function not resolved due to import
        // just match fc.name, but check it wasn't resolved.
        or (
            fc.possibleTargets contains [Function: name == "prototype" ]
            and fc.name matches "mergeObjects|mergeDeep" // leave out 'merge' here to prevent FPs
        )
    )
    and arguments[1] is [Expression arg: ]

FunctionCall fc: (
        fc.possibleTargets contains [Function: 
            name matches "defaults-deep|defaults|defaultsDeep"
        ]
        // due to the import type in TS, may not have function resolved
        or fc.name == "defaultsDeep"
    )
    // prevent dupes from lodash.defaultsDeep
    and not fc.instance is [Location: name matches "(?i)_|lodash|lod"]
    and arguments contains [Expression arg: 
        // don't trigger on destination object
        arg != fc.arguments[0]
    ]

