FunctionModel.Code:
class Promise {
    static any(iterable){
        let resolvedResults = new Array();
        let p = new Promise();
        for (let i of iterable){
            var elem = iterable[i];
            if (elem.resolved){
                resolvedResults.push(elem.resolved);
            }
            if (elem.rejected){
                p.rejected = elem.rejected;
            }
        }
        p.resolved = resolvedResults;
        return p;
    }
}

class Promise {
    static race(iterable){
        let resolvedResults = new Array();
        let p = new Promise();
        for (let i of iterable){
            var elem = iterable[i];
            if (elem.resolved){
                resolvedResults.push(elem.resolved);
            }
            if (elem.rejected){
                p.rejected = elem.rejected;
            }
        }
        p.resolved = resolvedResults;
        return p;
    }
}

class Promise {
    static all(iterable){
        let resolvedResults = new Array();
        let p = new Promise();
        for (let i of iterable){
            var elem = iterable[i];
            if (elem.resolved){
                resolvedResults.push(elem.resolved);
            }
            if (elem.rejected){
