}

class Promise {
    static allSettled(iterable){
        let resolvedResults = new Array();
        let p = new Promise();
        for (let i of iterable){
            var elem = iterable[i];
            if (elem.resolved){
                resolvedResults.push(elem.resolved);
            }
            if (elem.rejected){
                p.rejected = elem.rejected;
            }
        }
        p.resolved = resolvedResults;
        return p;
    }
}

class Promise {
    catch(onRejected) {
        let rejectedRet = onRejected(this.rejected);
    }
}

class Promise {
    static reject(reason) {
        let p = new Promise();
        p.rejected = reason;
        return p;
    }
}

class Promise {
    static resolve(value) {
        if (value == 'thenable') {
            value.then((arg) => {value.resolved = arg}, (arg) => {value.rejected = arg});
            return value;
        }
        let p = new Promise();
        p.resolved = value;
        return p;
    }
}

class Promise {
    then(onFulfilled, onRejected) {
        let fulFilledRet = onFulfilled(this.resolved);
        let rejectedRet = null;
        if (onRejected !== undefined){
            rejectedRet = onRejected(this.rejected);
        }
        let p = new Promise();
        if (fulFilledRet != null){
            p.resolved = fulFilledRet;
        }
        if (rejectedRet != null) {
            p.rejected = rejectedRet;
        }
        return p;
    }
}

class Promise {
    constructor(callback) {
        this.rejected = "";
        this.resolved = "";
        var self = this;
        callback((arg) => {self.resolved = arg}, (arg) => {self.rejected = arg});
    }
}

class Object {
    static getOwnPropertyNames(obj) {
        let propertyNames = new Array()
        for (var key in obj){
            propertyNames.push(key)
        }
        return propertyNames
    }
}

class Object {
    static getOwnPropertyDescriptor(obj, prop) {
        return { value: obj[prop] }
    }
}

class Object {
   static entries(obj) {
        let entriesArray = new Array()
        for (var key in obj){
            let entry = new Array()
            entry.push(key)
            entry.push(obj[key])
            entriesArray.push(entry)
        }
        return entriesArray
    }
}

class Object {
    static values(obj) {
        let valuesArray = new Array()
        for (var key in obj){
            valuesArray.push(obj[key])
        }
        return valuesArray
    }
}

class Object {
    static keys(obj) {
        let keysArray = new Array()
        for (var key in obj){
            keysArray.push(key)
        }
        return keysArray
    }
}

class Object {
    static getOwnPropertyDescriptors(obj) {
        var returnObj = {}
        for (var key in obj) {
            returnObj[key] = {
                value: obj[key]
            }
        }
        return returnObj;
    }
}

 class Object {
    static fromEntries(pairs) {
        let returnObj = {}
        for (let value of pairs) {
            returnObj[value[0]] = value[1]
        }
        return returnObj;
    }
}

