FunctionModel.Code:
class String {
    matchAll(regex) {
        let self = this;
        let iteratorObject = {}
        iteratorObject[Symbol.iterator] = function __JS_iterator() {
            var resultArr = new Array()
            resultArr.push(self);
            resultArr.push(self);

            var iter = {
                next: function __JS_iterator_next () {
                    var result = {
                        done: false,
                        value: resultArr
                    }
                    return result;
                }
            }
            return iter;
        }
        return iteratorObject;
    }
}

