CharacterizationRule.StructuralMatch:
Location loc:
    (
        /* match location.href or window.location.href */
        loc is [AccessLocation:
            not accessName matches "pathname|port|host(name)?|protocol|origin"
            and accessInstance is [Location locationAsInstance:
                possibleTypes contains [Type: name == "Location"]
                /* need to prevent duplicates with D20C6165 for Document.location */
                and (
                    /* either location here is a variable */
                    locationAsInstance is [VariableAccess: ]
                    /* or it's a field, in which case we need to make sure the instance isn't Document */
                    or locationAsInstance is [AccessLocation:
                        not accessInstance is [Location: possibleTypes contains [Type: name == "Document"]]
                    ]
                )
            ]
        ]
        /* match location on its own (when it's a variable). Only match on original location to prevent duplicates */
        or loc is [VariableAccess: variable.name == "location" ]
        /* match window.location on its own (when it's a field) */
        or loc is [AccessLocation:
            accessInstance is [Location: possibleTypes contains [Type: name == "Window"]]
            and name == "location"
        ]
    )
    /*
    *  can't check "not loc in " to exclude properties.
    *  That works for excluding "foo" in "location.foo", but not in "window.location.foo"
    *  as the access to "window" is _in_ window.location
    *  so we have to check the enclosing function to see if there's a separate access of
    *  the underlying property where the instance is the location we're referring to
    */
    and not enclosingFunction contains [AccessLocation:
        accessName matches "pathname|port|host(name)?|protocol|origin"
        and accessInstance is loc
        and accessInstance.sourceLocation == loc.sourceLocation
    ]
    and (
        not (
            loc in [AssignmentStatement: lhs.location is [Location l: l.transitiveBase === loc.transitiveBase]]
            or loc in [AssignmentStatement: lhs.location is [AccessLocation fa3: fa3.accessInstance === loc]]
        )
        or loc in [AssignmentStatement: rhs.location is [Location l2: l2.transitiveBase === loc.transitiveBase]]
    )

AccessLocation al:
    (
        al.accessName matches "URL|URLUnencoded|documentURI|baseURI"
        or (
            al.accessName == "location"
            and (
                not al in [AccessLocation:]
                or al in [AccessLocation:
                    not accessName matches "port|host(name)?|protocol|origin"
                ]
            )
        )
    )
    and al.accessInstance is [Location:
        possibleTypes contains [Type: name == "Document"]
    ]
    and (
        not (
            al in [AssignmentStatement: lhs.location is [Location l: l.transitiveBase === al.transitiveBase]]
            or al in [AssignmentStatement: lhs.location is [FieldAccess al3: al3.instance === al]]
        )
        or al in [AssignmentStatement: rhs.location is [Location l2: l2.transitiveBase === al.transitiveBase]]
    )

