FunctionModel.Code:
function __angularPipe_slice(iterable) {
    if (iterable == null) { return false; }
    let returnVal = new Array();
    if (typeof iterable[Symbol.iterator] === 'function') {
        for (let item of iterable) {
            let obj = new Object();
            obj.key = item[0];
            obj.value = item[1];
            returnVal.push(obj);
        }
    } else {
        for (let key in iterable) {
            let obj = new Object();
            obj.key = key; obj.value = iterable[key];
            returnVal.push(obj);
        }
    } return returnVal;
}

class SQLTransaction {
    executeSql(sqlStatement, arguments, callback, errorCallback) {
        callback(this, new SQLResultSet());
        errorCallback(this, new SQLError());
    }
}

